//! CLDR date and time interval formatting.
//!
//! The table is generated by tools/unicode/format/generate_intervals.py and
//! stores interval patterns split into their two sides plus each locale's
//! fallback format and the skeleton id table.

const std = @import("std");
const dates = @import("dates.zig");
const dates_data = @import("dates_data.zig");

const blob = @embedFile("intervals_data.bin");

const header_len = 24;
const locale_count = readU16(8);
const entry_count = readU32(12);
const string_length = readU32(16);
const skeleton_count = readU32(20);

const skeleton_offset = header_len;
const locale_offset = header_len + skeleton_count * 4;
const entry_offset = locale_offset + locale_count * 16;
const strings_offset = entry_offset + entry_count * 12;

comptime {
    if (blob.len < header_len or !std.mem.eql(u8, blob[0..4], "CJIV") or
        blob[4] != 2)
    {
        @compileError("invalid interval data");
    }
    if (strings_offset + @as(usize, string_length) != blob.len) {
        @compileError("invalid interval data lengths");
    }
}

// Skeleton ids (the first eight entries are stable style skeletons).
const skeleton_y_md = 0;
const skeleton_y_mmmd = 1;
const skeleton_y_mmmmd = 2;
const skeleton_y_mmmmeee = 3;
const skeleton_hm24 = 4;
const skeleton_hm12 = 5;

// Greatest-difference keys.
const key_year = 0;
const key_month = 1;
const key_day = 2;
const key_hour = 3;
const key_minute = 4;
const key_second = 5;
const key_day_period = 6;
const key_era = 7;

fn readU16(offset: usize) u16 {
    return std.mem.readInt(u16, blob[offset..][0..2], .little);
}

fn readU32(offset: usize) u32 {
    return std.mem.readInt(u32, blob[offset..][0..4], .little);
}

fn strAt(offset: u32) []const u8 {
    if (offset == 0) return "";
    return std.mem.sliceTo(blob[strings_offset + @as(usize, offset) ..], 0);
}

fn skeletonAt(index: usize) []const u8 {
    return strAt(readU32(skeleton_offset + index * 4));
}

fn findSkeleton(name: []const u8) ?u8 {
    var index: usize = 0;
    while (index < skeleton_count) : (index += 1) {
        if (std.mem.eql(u8, skeletonAt(index), name)) return @intCast(index);
    }
    return null;
}

const LocaleRecord = struct {
    id: []const u8,
    entry_start: u16,
    entry_count: u16,
    fallback: []const u8,
};

fn localeAt(index: usize) LocaleRecord {
    const base = locale_offset + index * 16;
    const id_offset = readU32(base);
    const id_length = blob[base + 4];
    return .{
        .id = blob[strings_offset + @as(usize, id_offset) ..][0..id_length],
        .entry_start = readU16(base + 6),
        .entry_count = readU16(base + 8),
        .fallback = strAt(readU32(base + 10)),
    };
}

fn lookupLocale(name: []const u8) ?LocaleRecord {
    var low: usize = 0;
    var high: usize = locale_count;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const record = localeAt(middle);
        switch (std.mem.order(u8, record.id, name)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return record,
        }
    }
    return null;
}

fn findLocale(name: []const u8) ?LocaleRecord {
    if (lookupLocale(name)) |record| return record;
    if (std.mem.indexOfAny(u8, name, "-_")) |position| {
        if (lookupLocale(name[0..position])) |record| return record;
    }
    return lookupLocale("en");
}

const Entry = struct {
    left: []const u8,
    right: []const u8,
};

fn findEntry(locale: LocaleRecord, skeleton: u8, key: u8) ?Entry {
    var low: usize = locale.entry_start;
    var high: usize = locale.entry_start + locale.entry_count;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const base = entry_offset + middle * 12;
        const value = blob[base];
        const entry_key = blob[base + 1];
        if (value < skeleton or (value == skeleton and entry_key < key)) {
            low = middle + 1;
        } else if (value > skeleton or entry_key > key) {
            high = middle;
        } else {
            return .{
                .left = strAt(readU32(base + 4)),
                .right = strAt(readU32(base + 8)),
            };
        }
    }
    return null;
}

fn fallbackSeparator(fallback: []const u8) []const u8 {
    const open = std.mem.indexOf(u8, fallback, "{0}") orelse return "\u{2013}";
    const close = std.mem.indexOfPos(u8, fallback, open + 3, "{1}") orelse
        return "\u{2013}";
    return fallback[open + 3 .. close];
}

fn applyFallback(
    allocator: std.mem.Allocator,
    fallback: []const u8,
    first: []const u8,
    second: []const u8,
) ![]u8 {
    var output = std.ArrayList(u8).empty;
    errdefer output.deinit(allocator);
    var index: usize = 0;
    while (index < fallback.len) {
        if (fallback[index] == '{' and index + 2 < fallback.len and
            fallback[index + 2] == '}')
        {
            if (fallback[index + 1] == '0') {
                try output.appendSlice(allocator, first);
            } else if (fallback[index + 1] == '1') {
                try output.appendSlice(allocator, second);
            }
            index += 3;
            continue;
        }
        try output.append(allocator, fallback[index]);
        index += 1;
    }
    return output.toOwnedSlice(allocator);
}

fn joinParts(
    allocator: std.mem.Allocator,
    fallback: []const u8,
    left: []const u8,
    right: []const u8,
) ![]u8 {
    _ = fallback;
    // The interval pattern's first part already includes the separator.
    return std.mem.concat(allocator, u8, &.{ left, right });
}

fn formatFallback(
    allocator: std.mem.Allocator,
    locale: LocaleRecord,
    locale_name: []const u8,
    start: dates.DateTime,
    end: dates.DateTime,
    style: dates.Style,
    time: bool,
) ![]u8 {
    const first = if (time)
        try dates.formatTimeAlloc(allocator, start, locale_name, style)
    else
        try dates.formatDateAlloc(allocator, start, locale_name, style);
    defer allocator.free(first);
    const second = if (time)
        try dates.formatTimeAlloc(allocator, end, locale_name, style)
    else
        try dates.formatDateAlloc(allocator, end, locale_name, style);
    defer allocator.free(second);
    return applyFallback(allocator, locale.fallback, first, second);
}

fn dateSkeleton(style: dates.Style) u8 {
    return switch (style) {
        .full => skeleton_y_mmmmeee,
        .long => skeleton_y_mmmmd,
        .medium => skeleton_y_mmmd,
        .short => skeleton_y_md,
    };
}

fn gregorianLocale(name: []const u8) ?dates_data.Locale {
    for (dates_data.locales) |locale| {
        if (std.mem.eql(u8, locale.id, name)) return locale;
    }
    if (std.mem.indexOfAny(u8, name, "-_")) |position| {
        for (dates_data.locales) |locale| {
            if (std.mem.eql(u8, locale.id, name[0..position])) return locale;
        }
    }
    return null;
}

fn usesTwelveHour(name: []const u8) bool {
    const locale = gregorianLocale(name) orelse return false;
    return std.mem.indexOfScalar(u8, locale.time_short, 'h') != null;
}

/// Format a date interval using CLDR interval patterns.
pub fn formatDateIntervalAlloc(
    allocator: std.mem.Allocator,
    start: dates.DateTime,
    end: dates.DateTime,
    locale_name: []const u8,
    style: dates.Style,
) ![]u8 {
    const locale = findLocale(locale_name) orelse return error.UnknownLocale;
    if (start.year == end.year and start.month == end.month and
        start.day == end.day)
    {
        return dates.formatDateAlloc(allocator, start, locale_name, style);
    }
    const key: u8 = if (start.year != end.year)
        key_year
    else if (start.month != end.month)
        key_month
    else
        key_day;
    if (findEntry(locale, dateSkeleton(style), key)) |entry| {
        const left = try dates.formatPatternAlloc(
            allocator,
            entry.left,
            start,
            locale_name,
            "UTC",
        );
        defer allocator.free(left);
        const right = try dates.formatPatternAlloc(
            allocator,
            entry.right,
            end,
            locale_name,
            "UTC",
        );
        defer allocator.free(right);
        return joinParts(allocator, locale.fallback, left, right);
    }
    return formatFallback(
        allocator,
        locale,
        locale_name,
        start,
        end,
        style,
        false,
    );
}

/// Format a time interval for the short style (hours and minutes).
pub fn formatTimeIntervalAlloc(
    allocator: std.mem.Allocator,
    start: dates.DateTime,
    end: dates.DateTime,
    locale_name: []const u8,
    style: dates.Style,
) ![]u8 {
    const locale = findLocale(locale_name) orelse return error.UnknownLocale;
    if (start.year != end.year or start.month != end.month or
        start.day != end.day)
    {
        return formatFallback(
            allocator,
            locale,
            locale_name,
            start,
            end,
            style,
            true,
        );
    }
    if (start.hour == end.hour and start.minute == end.minute and
        start.second == end.second)
    {
        return dates.formatTimeAlloc(allocator, start, locale_name, style);
    }
    const twelve = usesTwelveHour(locale_name);
    const key: u8 = if (twelve and start.hour / 12 != end.hour / 12)
        key_day_period
    else if (start.hour != end.hour)
        key_hour
    else if (start.minute != end.minute)
        key_minute
    else
        key_second;
    const skeleton: u8 = if (twelve) skeleton_hm12 else skeleton_hm24;
    if (style == .short) {
        if (findEntry(locale, skeleton, key)) |entry| {
            const left = try dates.formatPatternAlloc(
                allocator,
                entry.left,
                start,
                locale_name,
                "UTC",
            );
            defer allocator.free(left);
            const right = try dates.formatPatternAlloc(
                allocator,
                entry.right,
                end,
                locale_name,
                "UTC",
            );
            defer allocator.free(right);
            return joinParts(allocator, locale.fallback, left, right);
        }
    }
    return formatFallback(
        allocator,
        locale,
        locale_name,
        start,
        end,
        style,
        true,
    );
}

// ---------------------------------------------------------------------------
// Skeleton-based interval formatting (ICU DateIntervalFormat semantics).

const LetterFields = [52]u8;

fn letterIndex(letter: u8) ?usize {
    if (letter >= 'A' and letter <= 'Z') return letter - 'A';
    if (letter >= 'a' and letter <= 'z') return 26 + (letter - 'a');
    return null;
}

fn parseWidths(skeleton: []const u8, widths: *LetterFields) void {
    @memset(widths[0..], 0);
    for (skeleton) |letter| {
        if (letterIndex(letter)) |index| {
            if (widths[index] < std.math.maxInt(u8)) widths[index] += 1;
        }
    }
}

/// Normalize a skeleton for interval table matching the way ICU does:
/// `z` folds to `v`, `K`/`k` fold to `H`/`h`, and day-period letters are
/// dropped.
fn normalizeIntervalSkeleton(input: []const u8, buffer: []u8) ?[]const u8 {
    var length: usize = 0;
    for (input) |letter| {
        const mapped: ?u8 = switch (letter) {
            'z' => 'v',
            'K' => 'H',
            'k' => 'h',
            'a', 'b' => null,
            else => letter,
        };
        if (mapped) |value| {
            if (length == buffer.len) return null;
            buffer[length] = value;
            length += 1;
        }
    }
    return buffer[0..length];
}

const FieldKind = enum {
    era,
    year,
    month,
    day,
    day_period,
    hour,
    minute,
    second,
    millisecond,
};

fn largestDifference(start: dates.DateTime, end: dates.DateTime) ?FieldKind {
    if (start.year != end.year) return .year;
    if (start.month != end.month) return .month;
    if (start.day != end.day) return .day;
    if (start.hour / 12 != end.hour / 12) return .day_period;
    if (start.hour != end.hour) return .hour;
    if (start.minute != end.minute) return .minute;
    if (start.second != end.second) return .second;
    return null;
}

fn keyFor(field: FieldKind) u8 {
    return switch (field) {
        .era => key_era,
        .year => key_year,
        .month => key_month,
        .day => key_day,
        .day_period => key_day_period,
        .hour => key_hour,
        .minute => key_minute,
        .second, .millisecond => key_second,
    };
}

fn isSameDayTimeField(field: FieldKind) bool {
    return switch (field) {
        .day_period, .hour, .minute, .second, .millisecond => true,
        else => false,
    };
}

fn fieldLevel(letter: u8) i16 {
    return switch (letter) {
        'G' => 0,
        'y', 'Y', 'u', 'U', 'r' => 10,
        'Q', 'q', 'M', 'L', 'l', 'w', 'D' => 20,
        'W', 'E', 'e', 'c', 'F', 'd' => 30,
        'a', 'A' => 40,
        'H', 'h', 'K', 'k', 'J', 'j', 'C' => 50,
        'm' => 60,
        's' => 70,
        'S' => 80,
        else => -1,
    };
}

/// Whether the resolved pattern contains no field at or finer than `field`
/// (ICU SimpleDateFormat::isFieldUnitIgnored).
fn isFieldUnitIgnored(pattern: []const u8, field: FieldKind) bool {
    const target: i16 = switch (field) {
        .era => 0,
        .year => 10,
        .month => 20,
        .day => 30,
        .day_period => 40,
        .hour => 50,
        .minute => 60,
        .second => 70,
        .millisecond => 80,
    };
    var quoted = false;
    for (pattern) |byte| {
        if (byte == '\'') {
            quoted = !quoted;
            continue;
        }
        if (quoted) continue;
        const level = fieldLevel(byte);
        if (level >= 0 and target <= level) return false;
    }
    return true;
}

const BestMatch = struct {
    id: u8,
    difference: i8,
};

/// ICU DateIntervalInfo::getBestSkeleton distance scan over the skeletons the
/// locale defines.
fn bestMatch(locale: LocaleRecord, input: []const u8) ?BestMatch {
    var input_widths: LetterFields = undefined;
    parseWidths(input, &input_widths);
    var best: ?BestMatch = null;
    var best_distance: u32 = std.math.maxInt(u32);
    var index: usize = locale.entry_start;
    const end = locale.entry_start + locale.entry_count;
    while (index < end) {
        const base = entry_offset + index * 12;
        const id = blob[base];
        var next = index + 1;
        while (next < end and blob[entry_offset + next * 12] == id) next += 1;
        const candidate = skeletonAt(id);
        var candidate_widths: LetterFields = undefined;
        parseWidths(candidate, &candidate_widths);
        var distance: u32 = 0;
        var difference: i8 = 1;
        for (0..52) |slot| {
            const input_width = input_widths[slot];
            const candidate_width = candidate_widths[slot];
            if (input_width == candidate_width) continue;
            if (input_width == 0 or candidate_width == 0) {
                difference = -1;
                distance += 0x1000;
            } else if (slot == 'M' - 'A' and
                ((input_width <= 2 and candidate_width > 2) or
                    (input_width > 2 and candidate_width <= 2)))
            {
                distance += 0x100;
            } else {
                distance += if (input_width > candidate_width)
                    input_width - candidate_width
                else
                    candidate_width - input_width;
            }
        }
        if (distance < best_distance) {
            best_distance = distance;
            if (distance == 0) {
                best = .{ .id = id, .difference = 0 };
                break;
            }
            best = .{ .id = id, .difference = difference };
        }
        index = next;
    }
    return best;
}

/// Widen interval-pattern fields to the requested skeleton widths
/// (ICU DateIntervalFormat::adjustFieldWidth).
fn adjustIntervalPattern(
    pattern: []const u8,
    input_widths: *const LetterFields,
    best_widths: *const LetterFields,
    buffer: []u8,
) ?[]const u8 {
    var length: usize = 0;
    var index: usize = 0;
    var quoted = false;
    while (index < pattern.len) {
        const byte = pattern[index];
        if (byte == '\'') {
            quoted = !quoted;
            if (length == buffer.len) return null;
            buffer[length] = byte;
            length += 1;
            index += 1;
            continue;
        }
        if (quoted or letterIndex(byte) == null) {
            if (length == buffer.len) return null;
            buffer[length] = byte;
            length += 1;
            index += 1;
            continue;
        }
        var field_end = index;
        while (field_end < pattern.len and pattern[field_end] == byte) {
            field_end += 1;
        }
        const count = field_end - index;
        const skeleton_letter: u8 = if (byte == 'L') 'M' else byte;
        const slot = letterIndex(skeleton_letter) orelse {
            if (length + count > buffer.len) return null;
            @memcpy(buffer[length..][0..count], pattern[index..field_end]);
            length += count;
            index = field_end;
            continue;
        };
        var width = count;
        const best_count = best_widths[slot];
        const input_count = input_widths[slot];
        if (best_count == count and input_count > best_count) {
            width = input_count;
        }
        if (length + width > buffer.len) return null;
        var repetition: usize = 0;
        while (repetition < width) : (repetition += 1) {
            buffer[length] = byte;
            length += 1;
        }
        index = field_end;
    }
    return buffer[0..length];
}

fn hasLetter(skeleton: []const u8, letters: []const u8) bool {
    for (skeleton) |byte| {
        if (std.mem.indexOfScalar(u8, letters, byte) != null) return true;
    }
    return false;
}

const PatternEntry = union(enum) {
    unset,
    interval: struct {
        best: u8,
        key: u8,
        input_widths: LetterFields,
        with_date: bool,
    },
    fallback: []const u8,
};

const PatternSet = struct {
    entries: [8]PatternEntry = .{.unset} ** 8,
    storage: [8][80]u8 = undefined,
    storage_len: [8]u8 = .{0} ** 8,

    fn setFallback(self: *PatternSet, key: u8, skeleton: []const u8) void {
        const len: u8 = @intCast(@min(skeleton.len, self.storage[key].len));
        @memcpy(self.storage[key][0..len], skeleton[0..len]);
        self.storage_len[key] = len;
        self.entries[key] = .{ .fallback = self.storage[key][0..len] };
    }

    fn setInterval(
        self: *PatternSet,
        key: u8,
        best: u8,
        entry_key: u8,
        input_widths: *const LetterFields,
        with_date: bool,
    ) void {
        self.entries[key] = .{
            .interval = .{
                .best = best,
                .key = entry_key,
                .input_widths = input_widths.*,
                .with_date = with_date,
            },
        };
    }
};

/// Build the interval pattern set for a skeleton the way ICU's
/// DateIntervalFormat::initializePattern does.
fn buildPatternSet(
    locale: LocaleRecord,
    split: dates.SplitSkeleton,
    normalized_date: []const u8,
    normalized_time: []const u8,
    canonical: []const u8,
    set: *PatternSet,
) void {
    if (split.time.len > 0) {
        const best = bestMatch(locale, normalized_time);
        const found = best != null and best.?.difference != -1;
        if (found) {
            const id = best.?.id;
            const with_date = split.date.len > 0;
            var time_widths: LetterFields = undefined;
            parseWidths(normalized_time, &time_widths);
            if (findEntry(locale, id, key_minute) != null) {
                set.setInterval(key_minute, id, key_minute, &time_widths, with_date);
            }
            if (findEntry(locale, id, key_hour) != null) {
                set.setInterval(key_hour, id, key_hour, &time_widths, with_date);
            }
            if (findEntry(locale, id, key_day_period) != null) {
                set.setInterval(key_day_period, id, key_day_period, &time_widths, with_date);
            } else if (findEntry(locale, id, key_hour) != null) {
                set.setInterval(key_day_period, id, key_hour, &time_widths, with_date);
            }
        }
        if (split.date.len == 0) {
            // Time-only skeleton: date differences fall back to a yMd
            // prefixed pattern.
            var combined: [64]u8 = undefined;
            if (prependSkeleton("yMd", normalized_time, &combined)) |skeleton| {
                set.setFallback(key_day, skeleton);
                set.setFallback(key_month, skeleton);
                set.setFallback(key_year, skeleton);
                var era_buffer: [65]u8 = undefined;
                if (prependSkeleton("G", skeleton, &era_buffer)) |era_skeleton| {
                    set.setFallback(key_era, era_skeleton);
                }
            }
        } else if (found) {
            // Combined skeleton: date differences fall back to the full
            // skeleton, extended with any missing date fields.
            var buffer: [72]u8 = undefined;
            var length: usize = @min(canonical.len, buffer.len);
            @memcpy(buffer[0..length], canonical[0..length]);
            const steps = [_]struct { field: FieldKind, letter: u8 }{
                .{ .field = .day, .letter = 'd' },
                .{ .field = .month, .letter = 'M' },
                .{ .field = .year, .letter = 'y' },
                .{ .field = .era, .letter = 'G' },
            };
            for (steps) |step| {
                const present = switch (step.field) {
                    .day => hasLetter(split.date, "d"),
                    .month => hasLetter(split.date, "ML"),
                    .year => hasLetter(split.date, "yYuUrU"),
                    else => hasLetter(split.date, "G"),
                };
                if (present) continue;
                if (length == buffer.len) break;
                std.mem.copyBackwards(
                    u8,
                    buffer[1 .. length + 1],
                    buffer[0..length],
                );
                buffer[0] = step.letter;
                length += 1;
                set.setFallback(keyFor(step.field), buffer[0..length]);
            }
        }
        return;
    }
    if (split.date.len == 0) return;

    const best = bestMatch(locale, normalized_date);
    if (best == null or best.?.difference == -1) return;

    var input_storage: [72]u8 = undefined;
    var best_storage: [72]u8 = undefined;
    var input_length: usize = @min(normalized_date.len, input_storage.len);
    @memcpy(input_storage[0..input_length], normalized_date[0..input_length]);
    var best_length: usize = @min(skeletonAt(best.?.id).len, best_storage.len);
    @memcpy(best_storage[0..best_length], skeletonAt(best.?.id)[0..best_length]);
    var best_id = best.?.id;

    const steps = [_]struct { field: FieldKind, letter: u8 }{
        .{ .field = .day, .letter = 'd' },
        .{ .field = .month, .letter = 'M' },
        .{ .field = .year, .letter = 'y' },
        .{ .field = .era, .letter = 'G' },
    };
    for (steps) |step| {
        const key = keyFor(step.field);
        const input_skeleton = input_storage[0..input_length];
        const best_skeleton = best_storage[0..best_length];
        var input_widths: LetterFields = undefined;
        parseWidths(input_skeleton, &input_widths);
        if (findEntry(locale, best_id, key) != null) {
            set.setInterval(key, best_id, key, &input_widths, false);
            continue;
        }
        if (isFieldUnitIgnored(best_skeleton, step.field)) continue;
        var extended_input: [73]u8 = undefined;
        var extended_best: [73]u8 = undefined;
        if (prependSkeleton(&[_]u8{step.letter}, input_skeleton, &extended_input) == null) {
            continue;
        }
        if (prependSkeleton(&[_]u8{step.letter}, best_skeleton, &extended_best) == null) {
            continue;
        }
        const extended_input_skeleton = extended_input[0 .. input_length + 1];
        const extended_best_skeleton = extended_best[0 .. best_length + 1];
        var found_id = findSkeleton(extended_best_skeleton);
        if (found_id == null and best.?.difference == 0) {
            if (bestMatch(locale, extended_best_skeleton)) |extended| {
                found_id = extended.id;
            }
        }
        const id = found_id orelse continue;
        if (findEntry(locale, id, key) == null) continue;
        var extended_widths: LetterFields = undefined;
        parseWidths(extended_input_skeleton, &extended_widths);
        set.setInterval(key, id, key, &extended_widths, false);
        input_length += 1;
        @memcpy(input_storage[0..input_length], extended_input_skeleton);
        best_length += 1;
        @memcpy(best_storage[0..best_length], extended_best_skeleton);
        best_id = id;
    }
}

fn prependSkeleton(prefix: []const u8, skeleton: []const u8, buffer: []u8) ?[]const u8 {
    if (prefix.len + skeleton.len > buffer.len) return null;
    @memcpy(buffer[0..prefix.len], prefix);
    @memcpy(buffer[prefix.len..][0..skeleton.len], skeleton);
    return buffer[0 .. prefix.len + skeleton.len];
}

fn fallbackRange(
    allocator: std.mem.Allocator,
    locale: LocaleRecord,
    locale_name: []const u8,
    start: dates.DateTime,
    end: dates.DateTime,
    skeleton: []const u8,
) ![]u8 {
    const first = try dates.formatSkeletonAlloc(allocator, start, locale_name, skeleton);
    defer allocator.free(first);
    const second = try dates.formatSkeletonAlloc(allocator, end, locale_name, skeleton);
    defer allocator.free(second);
    return applyFallback(allocator, locale.fallback, first, second);
}

fn fallbackFormat(
    allocator: std.mem.Allocator,
    locale: LocaleRecord,
    locale_name: []const u8,
    start: dates.DateTime,
    end: dates.DateTime,
    skeleton: []const u8,
    split: dates.SplitSkeleton,
    from_to_on_same_day: bool,
    gregorian: *const dates_data.Locale,
) ![]u8 {
    if (from_to_on_same_day and split.date.len > 0 and split.time.len > 0) {
        // Same day, time differs: format the date once, then the time range.
        const date_text = try dates.formatSkeletonAlloc(
            allocator,
            start,
            locale_name,
            split.date,
        );
        defer allocator.free(date_text);
        const time_range = try fallbackRange(
            allocator,
            locale,
            locale_name,
            start,
            end,
            split.time,
        );
        defer allocator.free(time_range);
        return dates.substituteDateTimePattern(
            allocator,
            gregorian.date_time_interval,
            date_text,
            time_range,
        );
    }
    return fallbackRange(allocator, locale, locale_name, start, end, skeleton);
}

/// Format a date/time interval using an ICU date skeleton
/// (DateIntervalFormat semantics).
pub fn formatSkeletonIntervalAlloc(
    allocator: std.mem.Allocator,
    start: dates.DateTime,
    end: dates.DateTime,
    locale_name: []const u8,
    skeleton: []const u8,
) ![]u8 {
    const locale = findLocale(locale_name) orelse return error.UnknownLocale;
    var canonical_buffer: [64]u8 = undefined;
    const canonical = dates.canonicalSkeleton(skeleton, &canonical_buffer) orelse
        return dates.formatSkeletonAlloc(allocator, start, locale_name, skeleton);
    var gregorian_storage = gregorianLocale(locale_name) orelse
        gregorianLocale("en").?;
    const gregorian = &gregorian_storage;

    const difference = largestDifference(start, end) orelse
        return dates.formatSkeletonAlloc(allocator, start, locale_name, canonical);
    const field = difference;
    const from_to_on_same_day = isSameDayTimeField(field);
    const key = keyFor(field);

    var date_part_buffer: [32]u8 = undefined;
    var time_part_buffer: [32]u8 = undefined;
    const split = dates.splitSkeleton(
        gregorian,
        canonical,
        &date_part_buffer,
        &time_part_buffer,
    );
    var normalized_date_buffer: [32]u8 = undefined;
    var normalized_time_buffer: [32]u8 = undefined;
    const normalized_date = normalizeIntervalSkeleton(
        split.date,
        &normalized_date_buffer,
    ) orelse split.date;
    const normalized_time = normalizeIntervalSkeleton(
        split.time,
        &normalized_time_buffer,
    ) orelse split.time;

    var patterns = PatternSet{};
    buildPatternSet(
        locale,
        split,
        normalized_date,
        normalized_time,
        canonical,
        &patterns,
    );

    switch (patterns.entries[key]) {
        .unset => {
            if (isFieldUnitIgnored(canonical, field)) {
                return dates.formatSkeletonAlloc(
                    allocator,
                    start,
                    locale_name,
                    canonical,
                );
            }
            return fallbackFormat(
                allocator,
                locale,
                locale_name,
                start,
                end,
                canonical,
                split,
                from_to_on_same_day,
                gregorian,
            );
        },
        .fallback => |fallback_skeleton| {
            return fallbackFormat(
                allocator,
                locale,
                locale_name,
                start,
                end,
                fallback_skeleton,
                split,
                from_to_on_same_day,
                gregorian,
            );
        },
        .interval => |interval| {
            const entry = findEntry(locale, interval.best, interval.key) orelse
                return fallbackFormat(
                    allocator,
                    locale,
                    locale_name,
                    start,
                    end,
                    canonical,
                    split,
                    from_to_on_same_day,
                    gregorian,
                );
            var best_widths: LetterFields = undefined;
            parseWidths(skeletonAt(interval.best), &best_widths);
            var left_buffer: [192]u8 = undefined;
            var right_buffer: [192]u8 = undefined;
            const left = adjustIntervalPattern(
                entry.left,
                &interval.input_widths,
                &best_widths,
                &left_buffer,
            ) orelse entry.left;
            const right = adjustIntervalPattern(
                entry.right,
                &interval.input_widths,
                &best_widths,
                &right_buffer,
            ) orelse entry.right;
            const left_text = try dates.formatPatternAlloc(
                allocator,
                left,
                start,
                locale_name,
                "UTC",
            );
            defer allocator.free(left_text);
            const right_text = try dates.formatPatternAlloc(
                allocator,
                right,
                end,
                locale_name,
                "UTC",
            );
            defer allocator.free(right_text);
            const time_range = try std.mem.concat(
                allocator,
                u8,
                &.{ left_text, right_text },
            );
            defer allocator.free(time_range);
            if (interval.with_date) {
                // ICU concatSingleDate2TimeInterval: present the date once,
                // followed by the time range.
                const date_text = try dates.formatSkeletonAlloc(
                    allocator,
                    start,
                    locale_name,
                    split.date,
                );
                defer allocator.free(date_text);
                return dates.substituteDateTimePattern(
                    allocator,
                    gregorian.date_time_interval,
                    date_text,
                    time_range,
                );
            }
            return allocator.dupe(u8, time_range);
        },
    }
}

test "date interval formatting" {
    const testing = @import("std").testing;
    const allocator = testing.allocator;
    const start = dates.fromUnixSeconds(1705320000, 0); // 2024-01-15 12:00
    const next_day = dates.fromUnixSeconds(1705586400, 0); // 2024-01-18 12:00
    const next_month = dates.fromUnixSeconds(1710763200, 0); // 2024-03-18 12:00
    const next_year = dates.fromUnixSeconds(1742299200, 0); // 2025-03-18 12:00

    const day_text = try formatDateIntervalAlloc(
        allocator,
        start,
        next_day,
        "en",
        .medium,
    );
    defer allocator.free(day_text);
    try testing.expectEqualStrings("Jan 15\u{2009}\u{2013}\u{2009}18, 2024", day_text);

    const month_text = try formatDateIntervalAlloc(
        allocator,
        start,
        next_month,
        "en",
        .medium,
    );
    defer allocator.free(month_text);
    try testing.expectEqualStrings("Jan 15\u{2009}\u{2013}\u{2009}Mar 18, 2024", month_text);

    const year_text = try formatDateIntervalAlloc(
        allocator,
        start,
        next_year,
        "en",
        .medium,
    );
    defer allocator.free(year_text);
    try testing.expectEqualStrings(
        "Jan 15, 2024\u{2009}\u{2013}\u{2009}Mar 18, 2025",
        year_text,
    );

    const short_text = try formatDateIntervalAlloc(
        allocator,
        start,
        next_day,
        "en",
        .short,
    );
    defer allocator.free(short_text);
    try testing.expectEqualStrings(
        "1/15/2024\u{2009}\u{2013}\u{2009}1/18/2024",
        short_text,
    );
}

test "time interval formatting" {
    const testing = @import("std").testing;
    const allocator = testing.allocator;
    const start = dates.fromUnixSeconds(1705320000, 0);
    const later = dates.fromUnixSeconds(1705329000, 0); // +2.5 hours
    const text = try formatTimeIntervalAlloc(
        allocator,
        start,
        later,
        "en",
        .short,
    );
    defer allocator.free(text);
    try testing.expectEqualStrings(
        "12:00\u{2009}\u{2013}\u{2009}2:30\u{202f}PM",
        text,
    );
}

test "interval conformance" {
    const testing = @import("std").testing;
    const allocator = testing.allocator;
    const fixture = @embedFile("interval_conformance.bin");
    try testing.expect(fixture.len >= 12);
    try testing.expectEqualStrings("CJI1", fixture[0..4]);
    const case_count = std.mem.readInt(u32, fixture[8..12], .little);
    var cursor: usize = 12;
    var failures: usize = 0;
    var total: usize = 0;
    var printed: usize = 0;
    for (0..case_count) |_| {
        const locale_length = fixture[cursor];
        const kind = fixture[cursor + 1];
        const style_index = fixture[cursor + 2];
        const start_seconds = std.mem.readInt(i64, fixture[cursor + 4 ..][0..8], .little);
        const end_seconds = std.mem.readInt(i64, fixture[cursor + 12 ..][0..8], .little);
        const expected_length = std.mem.readInt(u16, fixture[cursor + 20 ..][0..2], .little);
        cursor += 24;
        const locale_name = fixture[cursor .. cursor + locale_length];
        cursor += locale_length;
        const expected = fixture[cursor .. cursor + expected_length];
        cursor += expected_length;
        const style: dates.Style = switch (style_index) {
            0 => .full,
            1 => .long,
            2 => .medium,
            else => .short,
        };
        const start = dates.fromUnixSeconds(start_seconds, 0);
        const end = dates.fromUnixSeconds(end_seconds, 0);
        total += 1;
        const actual = (if (kind == 0)
            formatDateIntervalAlloc(allocator, start, end, locale_name, style)
        else
            formatTimeIntervalAlloc(allocator, start, end, locale_name, style)) catch |err| {
            failures += 1;
            if (printed < 40) {
                printed += 1;
                std.debug.print(
                    "interval mismatch {s} kind {d} style {d}: {s}\n",
                    .{ locale_name, kind, style_index, @errorName(err) },
                );
            }
            continue;
        };
        defer allocator.free(actual);
        if (!std.mem.eql(u8, actual, expected)) {
            failures += 1;
            if (printed < 40) {
                printed += 1;
                std.debug.print(
                    "interval mismatch {s} kind {d} style {d}: got '{s}' expected '{s}'\n",
                    .{ locale_name, kind, style_index, actual, expected },
                );
            }
        }
    }
    std.debug.print("interval conformance: {d}/{d} passed\n", .{ total - failures, total });
    try testing.expect(failures == 0);
}

test "interval skeleton conformance" {
    const testing = @import("std").testing;
    const allocator = testing.allocator;
    const fixture = @embedFile("interval_skeleton_conformance.bin");
    try testing.expect(fixture.len >= 12);
    try testing.expectEqualStrings("CJIS", fixture[0..4]);
    const case_count = std.mem.readInt(u32, fixture[8..12], .little);
    var cursor: usize = 12;
    var failures: usize = 0;
    var total: usize = 0;
    var printed: usize = 0;
    for (0..case_count) |_| {
        const locale_length = fixture[cursor];
        const skeleton_length = fixture[cursor + 1];
        const start = dates.DateTime{
            .year = std.mem.readInt(i16, fixture[cursor + 4 ..][0..2], .little),
            .month = fixture[cursor + 6],
            .day = fixture[cursor + 7],
            .hour = fixture[cursor + 8],
            .minute = fixture[cursor + 9],
            .second = fixture[cursor + 10],
        };
        const end = dates.DateTime{
            .year = std.mem.readInt(i16, fixture[cursor + 12 ..][0..2], .little),
            .month = fixture[cursor + 14],
            .day = fixture[cursor + 15],
            .hour = fixture[cursor + 16],
            .minute = fixture[cursor + 17],
            .second = fixture[cursor + 18],
        };
        const expected_length = std.mem.readInt(u16, fixture[cursor + 20 ..][0..2], .little);
        cursor += 24;
        const locale_name = fixture[cursor .. cursor + locale_length];
        cursor += locale_length;
        const skeleton = fixture[cursor .. cursor + skeleton_length];
        cursor += skeleton_length;
        const expected = fixture[cursor .. cursor + expected_length];
        cursor += expected_length;
        total += 1;
        const actual = formatSkeletonIntervalAlloc(
            allocator,
            start,
            end,
            locale_name,
            skeleton,
        ) catch |err| {
            failures += 1;
            if (printed < 40) {
                printed += 1;
                std.debug.print(
                    "skeleton interval error {s} {s}: {s}\n",
                    .{ locale_name, skeleton, @errorName(err) },
                );
            }
            continue;
        };
        defer allocator.free(actual);
        if (!std.mem.eql(u8, actual, expected)) {
            failures += 1;
            if (printed < 40) {
                printed += 1;
                std.debug.print(
                    "skeleton interval mismatch {s} {s} {d}-{d}-{d} {d}:{d} -> {d}-{d}-{d} {d}:{d}: got '{s}' expected '{s}'\n",
                    .{
                        locale_name,
                        skeleton,
                        start.year,
                        start.month,
                        start.day,
                        start.hour,
                        start.minute,
                        end.year,
                        end.month,
                        end.day,
                        end.hour,
                        end.minute,
                        actual,
                        expected,
                    },
                );
            }
        }
    }
    std.debug.print("interval skeleton conformance: {d}/{d} passed\n", .{ total - failures, total });
    try testing.expect(failures == 0);
}
